# install-dashboards.sh - copy the Zyberon dashboards to /var/www/sentra/dashboards (previous copy kept as
# dashboards.prev) and print how nginx protects the portal, so the /dashboards/ location can be added behind the
# same login. Does NOT change nginx.
#   run from the folder that holds this script:  sudo bash install-dashboards.sh
#   undo:                                         sudo bash install-dashboards.sh --rollback
set -euo pipefail
DEST=/var/www/sentra/dashboards
HERE="$(cd "$(dirname "$0")" && pwd)"
[ "$(id -u)" = 0 ] || { echo "run with sudo"; exit 1; }

if [ "${1:-}" = "--rollback" ]; then
  [ -d "$DEST.prev" ] || { echo "no previous copy ($DEST.prev)"; exit 1; }
  rm -rf "$DEST.bad"; mv "$DEST" "$DEST.bad"; mv "$DEST.prev" "$DEST"; echo "restored the previous dashboards"; exit 0
fi

for f in index.html add-server.html network-discovery.html scope-studio.html discovery-studio.html cmdb-studio.html asset-coverage.html cmdb-deps.html digital-twin.html impl-plan.html browsing-monitor.html network-access.html executive-dashboard.html live-status.html platform-map.html custom-dashboards.html phishing-simulation.html brand-protection.html dark-web-watch.html dfir.html incident-response.html appsec.html apppt.html crosswalk.html gap-analysis.html grc-dashboard.html grc-register.html ia-resilience.html insider-risk.html sama-audit.html device-config.html asset-studio.html lifecycle-studio.html eam.html cost-studio.html owner-studio.html remote-console.html dr-studio.html vsphere-studio.html virtual-network-map.html vendor/guacamole-common.js manageengine.html support-center.html tickets.html capacity.html support-contracts.html head-of-it.html network-flows.html apm-claims-portal.html portal-traffic.html soc-overview.html soc-console.html soc-alerts.html soc-cases.html soc-hunt.html soc-ti.html vendor/zyb-charts.js vendor/zyb-copilot.js vendor/zyb-secops.css soc-tickets.html network-engineer.html network-connectivity.html network-onboarding.html network-dashboard.html network-route-map.html wan-optimization.html fortigate-fleet.html mimecast-actions.html aramco-ccc.html branch-connectivity.html ipam.html ncm.html change-log.html vendor/zyb-ncm.js vendor/zyb-ipam.js switch-port-map.html network-map.html rogue-detection.html audit-log.html it-audit.html audit-dashboard.html audit-command.html sama-it-audit.html audit-ccm.html audit-analytics.html audit-repo.html vendor/zyb-arepo.js pdpl-intel.html dept-checklist.html vuln-dashboard.html live-scan.html mobile-test.html vapt-studio.html vuln-inventory.html risk-prioritization.html ai-pentest.html audit-inspections.html issues.html risk-control.html vapt-center.html vapt-workflow.html attack-surface.html scan-assurance.html vuln-scans.html vendor/zyb-vulnscan.js vendor/zyb-deptcheck.js audit-start.html inter