cs.html security-controls.html iso27001.html iso-lifecycle.html sama-ia.html compliance-assistant.html vendor/zyb-assist.js vendor/zyb-pdpl.js vendor/zyb-form-hints.js vendor/zyb-pdpl-ar.js vendor/zyb-update.js vendor/zyb-world.js aiops.html asset-ownership.html people-inventory.html grc-workspace.html risk-studio.html risk-command.html credential-security.html databases.html db-morning.html db-dashboard.html db-health-statement.html db-connections.html app-route-map.html db-sessions.html apm.html vendor/zyb-apmx.js oracle-tuning.html db-servers.html db-audit.html oracle-licences.html oracle-licence-report.html app-audit.html compliance-map.html live-compliance.html domains.html vendor/zyb-renewals.js certificates.html vendor/zyb-certpilot.js db-replication.html user-management.html ad-manage.html identity-signin.html solution-admin.html handover.html applications.html webapps.html business-services.html vendor/zyb-bizsvc.js ai-dba.html ai-sql-dba.html ai-app-manager.html ai-grc-consultant.html log-assurance.html pipeline-health.html ai-virt-admin.html ai-zscaler-engineer.html ai-ksc-engineer.html connections.html my-work.html my-workflow.html my-workspace.html vendor/zyb-dash.js vendor/zyb-errors.js vendor/zyb-print.js vendor/zyb-autorefresh.js vendor/zyb-brand.js vendor/zyb-home.js vendor/zyb-sla.js vendor/zyb-avail.js vendor/zyb-itamdel.js vendor/zyb-netinv.js vendor/zyb-m365.js vendor/zyb-siem.js vendor/zyb-assetreg.js vendor/zyb-discprog.js vendor/zyb-roles.js vendor/zyb-adacct.js vendor/zyb-siemconn.js vendor/zyb-discovery.js vendor/zyb-tiles.js vendor/zyb-vmuse.js vendor/zyb-lang.js vendor/zyb-ar.js vendor/zyb-look.js vendor/zyb-look.css vendor/zyb-vivid.css vendor/zyb-click.js vendor/zyb-xlsx.js vendor/discovery-module.js vendor/discovery.ar.json vendor/zyb-sysadmin.js vendor/zyb-sysadmin.css vendor/zyb-soc.js vendor/zyb-eml.js vendor/zyb-soc.css vendor/zyb-display.js vendor/zyb-fullview.js vendor/zyb-early.js vendor/zyb-theme.css vendor/zyb-theme.js vendor/zyb-tabler.css vendor/tabler/tabler.min.css vendor/tabler/tabler-icons.min.css vendor/tabler/fonts/tabler-icons.woff2 build-static.js; do
  [ -f "$HERE/$f" ] || { echo "missing $f - copy the whole dashboards/server folder"; exit 1; }
done
[ -f "$HERE/vendor/zyb-org.js" ] || { echo "missing vendor/zyb-org.js (the brand setting) - run: node tools/brand/apply-brand.js"; exit 1; }
STAGE="$DEST.new"; rm -rf "$STAGE"; mkdir -p "$STAGE/vendor"
cp "$HERE"/*.html "$STAGE/"; cp "$HERE"/vendor/*.js "$STAGE/vendor/"; cp "$HERE"/vendor/*.json "$STAGE/vendor/" 2>/dev/null || true; cp "$HERE"/vendor/*.css "$STAGE/vendor/" 2>/dev/null || true
cp -r "$HERE/vendor/tabler" "$STAGE/vendor/"   # Tabler (MIT), self-hosted: theme layer, components, icon font
[ -d "$HERE/vendor/fonts" ] && cp -r "$HERE/vendor/fonts" "$STAGE/vendor/"   # the company typeface of the light look (Raleway, OFL), self-hosted
BUILD="$(date +%Y%m%d%H%M%S)"
sed -i "s/__ZYB_BUILD__/$BUILD/" "$STAGE/vendor/zyb-menu.js"   # cache stamp for the add-on scripts
printf '{"build":"%s"}\n' "$BUILD" > "$STAGE/build.json"   # vendor/zyb-update.js: open pages notice this build and refresh by themselves
# the page list (zyb-nav.js) is built into the two scripts that read it, so the portal menu and the dashboard sidebar are
# drawn at once, in the same moment as before, and never wait on (or lose) a second download
for t in zyb-menu.js zyb-dash.js; do
  # the brand setting (zyb-org.js) goes in first: the page list and the menu read the company name from it
  { cat "$STAGE/vendor/zyb-org.js"; echo; cat "$STAGE/vendor/zyb-nav.js"; echo; cat "$STAGE/vendor/$t"; } > "$STAGE/vendor/$t.tmp" && mv "$STAGE/vendor/$t.tmp" "$STAGE/vendor/$t"
  grep -q "window.ZYB_ORG = " "$STAGE/vendor/$t" || { echo "could not build the brand setting into $t - nothing changed"; rm -rf "$STAGE"; exit 1; }
  grep -q "window.ZYB_NAV = " "$STAGE/vendor/$t" || { echo "could not build the menu into $t - nothing changed"; rm -rf "$STAGE"; exit 1; }
done
# static build (build-static.js): inline scripts into files for the strict Content-Security-Policy, ?v=<build> on every
# script / stylesheet for long browser caching, zyb-display built into zyb-dash, pre-compressed .gz copies
NODE="$(command -v node || true)"
[ -n "$NODE" ] || NODE="$(systemctl show -p ExecStart --value sentra-itam 2>/dev/null | sed -n 's/.*path=\([^ ;]*\).*/\1/p' | head -n1)"
[ -n "$NODE" ] && [ -x "$NODE" ] || { echo "node not found (needed for the static build) - nothing changed"; rm -rf "$STAGE"; exit 1; }
"$NODE" "$HERE/build-static.js" "$STAGE" "$BUILD" || { echo "static build failed - nothing changed"; rm -rf "$STAGE"; exit 1; }
# nginx already ENFORCES the strict policy (harden-web.sh): a build that is not marked safe for it would stop pages working
if grep -qs '^add_header Content-Security-Policy "default-src' /etc/nginx/snippets/zyb-dash-headers.conf && ! grep -q '"csp": *"strict"' "$STAGE/.zyb-static.json"; then
  echo "nginx enforces the strict Content-Security-Policy but this build still has inline script (list above) - nothing changed"; rm -rf "$STAGE"; exit 1
fi
chown -R root:root "$STAGE"; find "$STAGE" -type d -exec chmod 755 {} +; find "$STAGE" -type f -exec chmod 644 {} +
if [ -d "$DEST" ]; then rm -rf "$DEST.prev"; mv "$DEST" "$DEST.prev"; fi
mv "$STAGE" "$DEST"
echo "==> dashboards installed in $DEST ($(ls "$DEST"/*.html | wc -l) pages)"

echo
echo "==> how nginx protects the portal (send this output so the /dashboards/ location can be added)"
nginx -T 2>/dev/null | grep -nE 'server_name|listen 443|auth_request|location = /auth|location / |location /api/soc|error_page 401|ssl_certificate ' | head -40 || true   # information only: head closing the pipe early must not fail the install (pipefail)
echo
echo "nginx was not changed."
